import React, { useEffect, useState } from "react";
import axios from "axios";

export default function PaymentNumber({ token, role }) {
  const [bkash, setBkash] = useState("");
  const [nagad, setNagad] = useState("");

  // লোড পেমেন্ট নাম্বার
  useEffect(() => {
    axios
      .get("http://localhost:8080/api/payment-config")
      .then((res) => {
        const data = res.data;
        const bkashConfig = data.find((c) => c.method === "bKash");
        const nagadConfig = data.find((c) => c.method === "Nagad");

        if (bkashConfig) setBkash(bkashConfig.number);
        if (nagadConfig) setNagad(nagadConfig.number);
      })
      .catch((err) => console.error("Error loading payment configs:", err));
  }, []);

  // আপডেট পেমেন্ট নাম্বার (শুধু অ্যাডমিন)
  const saveNumber = (method, number) => {
    axios
      .post(
        "http://localhost:8080/api/payment-config/admin/update",
        null,
        {
          params: { method, number },
          headers: { Authorization: `Bearer ${token}` }
        }
      )
      .then(() => alert(`${method} number updated successfully`))
      .catch((err) => console.error("Error saving payment number:", err));
  };

  // ইনপুট ফিল্ড (এডিটেবল কিনা চেক)
  const renderField = (label, color, value, setValue, method) => (
    <div
      style={{
        border: "1px solid #ccc",
        padding: "15px",
        borderRadius: "5px",
        marginBottom: "20px",
        backgroundColor: "#f9f9f9"
      }}
    >
      <h3 style={{ marginBottom: "10px", color }}>{label}</h3>
      <input
        type="text"
        value={value}
        placeholder={`Enter ${label}`}
        onChange={(e) => setValue(e.target.value)}
        disabled={role !== "ADMIN"} // ✅ অ্যাডমিন ছাড়া কেউ লিখতে পারবে না
        style={{
          width: "100%",
          padding: "8px",
          border: "1px solid #ccc",
          borderRadius: "4px",
          marginBottom: "8px"
        }}
      />
      {role === "ADMIN" && (
        <button
          onClick={() => saveNumber(method, value)}
          style={{
            backgroundColor: color,
            color: "white",
            padding: "8px 15px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer"
          }}
        >
          Save {label}
        </button>
      )}
    </div>
  );

  return (
    <div style={{ padding: "20px", maxWidth: "500px", margin: "auto" }}>
      <h2 style={{ textAlign: "center" }}>Payment Number Settings</h2>

      {renderField("বিকাশ নাম্বার", "#d81b60", bkash, setBkash, "bKash")}
      {renderField("নগদ নাম্বার", "#ff6f00", nagad, setNagad, "Nagad")}
    </div>
  );
}
